function test($name,$fn){global$passed,$failed;try{$fn();$passed++;echo'PASS '.$name.PHP_EOL;}catch(Throwable$e){$failed++;echo'FAIL '.$name.': '.$e->getMessage().PHP_EOL;}finally{sess_file::close();sess_mystep::close();}}
function dirFor($name){global$scratch;$p=$scratch.'/'.$name;if(!is_dir($p))mkdir($p,0700,true);return$p;}
function rmTree($p){if(is_link($p)||is_file($p))unlink($p);elseif(is_dir($p)){foreach(new FilesystemIterator($p)as$f)rmTree($f->getPathname());rmdir($p);}}
function startJob($x){$env=getenv();$env['SESSION_REVIEW_JOB']=base64_encode(json_encode($x));$proc=proc_open([PHP_BINARY,__FILE__],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes,null,$env);fclose($pipes[0]);return[$proc,$pipes];}
function finishJob($j){list($proc,$pipes)=$j;$out=stream_get_contents($pipes[1]);$err=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);$code=proc_close($proc);if($code!==0)throw new RuntimeException('Child failed: '.$err.' '.$out);if($err!=='')throw new RuntimeException($err);return$out;}
function nativeJob($h,$p,$schema,$extra=[]){return json_decode(finishJob(startJob($extra+['type'=>'native','handler'=>$h,'path'=>$p,'schema'=>$schema])),true);}
function parallelCount($h,$p,$schema){$jobs=[];for($i=0;$i<8;$i++)$jobs[]=startJob(['handler'=>$h,'path'=>$p,'schema'=>$schema]);foreach($jobs as$j)same('ok',finishJob($j));check(configuredHandler($h,$p,$schema));same('8',$h::read('shared'));$h::close();}
